input.content:
:root {
  --paper: #f7f2e8;
  --paper-deep: #efe7d8;
  --card: #fffcf5;
  --line: #e2d7c4;
  --ink: #2e2920;
  --ink-soft: #6f6555;
  --bee: #f2c230;
  --bee-edge: #6b4e0e;
  --accent: #b5541b;
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--paper); color: var(--ink); }
body {
  font: 15px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}
#app { display: grid; grid-template-rows: 52px 1fr 60px; height: 100vh; }
body.capture #app { grid-template-rows: 52px 1fr; }
body.capture #controls { display: none; }

#bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 20px; border-bottom: 1px solid var(--line);
}
#title { font-size: 17px; font-weight: 600; }
#title span { font-weight: 400; color: var(--ink-soft); margin-left: 10px; }
#season { display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 500; }
#season-swatch {
  width: 14px; height: 14px; border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, .15); background: var(--paper-deep);
}

#main { display: grid; grid-template-columns: 1fr 312px; min-height: 0; }
#stage { position: relative; min-width: 0; min-height: 0; overflow: hidden; touch-action: none; }
#map { position: absolute; inset: 0; width: 100%; height: 100%; cursor: grab; }
#map.dragging { cursor: grabbing; }
#loading {
  position: absolute; inset: 0; display: grid; place-items: center;
  color: var(--ink-soft); font-size: 16px; background: var(--paper);
}
#loading.hidden { display: none; }

#panel {
  border-left: 1px solid var(--line); background: var(--card);
  padding: 16px 18px; overflow-y: auto; font-size: 14px;
}
#panel h2 { font-size: 18px; margin: 0 0 2px; }
#panel h3 { font-size: 14px; margin: 16px 0 6px; color: var(--ink-soft); font-weight: 600; }
#panel p { margin: 0 0 6px; }
#panel .muted { color: var(--ink-soft); }
#panel ul { list-style: none; margin: 0; padding: 0; }
#panel li { padding: 6px 0; border-top: 1px solid var(--line); }
#panel li:first-child { border-top: 0; }
#panel li.latest { background: #fbf0cf; margin: 0 -8px; padding: 6px 8px; border-radius: 6px; }
#panel .when { color: var(--ink-soft); font-size: 12.5px; }
#panel .quote { font-style: italic; }
.lifebar { height: 8px; border-radius: 4px; background: var(--paper-deep); overflow: hidden; margin: 8px 0 4px; }
.lifebar div { height: 100%; background: var(--bee); border-right: 1px solid var(--bee-edge); }
.lifebar.low div { background: #e0623a; }
.legend li { display: flex; align-items: center; gap: 10px; border-top: 0 !important; padding: 4px 0 !important; }
.legend canvas { flex: none; }
.stats { display: grid; grid-template-columns: 1fr auto; gap: 2px 12px; }
.stats span:nth-child(even) { text-align: right; font-variant-numeric: tabular-nums; }
.tag { display: inline-block; padding: 0 6px; border-radius: 4px; font-size: 12.5px; margin-right: 4px; }
.tag.s1 { background: #d6efee; color: #0e6563; }
.tag.s2 { background: #f6d9ec; color: #8a1f6b; }
.tag.trig { background: var(--paper-deep); color: var(--ink-soft); }

#controls {
  display: flex; align-items: center; gap: 16px;
  padding: 0 20px; border-top: 1px solid var(--line);
}
#play {
  min-width: 76px; height: 36px; border-radius: 18px; border: 1px solid var(--bee-edge);
  background: var(--bee); color: var(--ink); font: inherit; font-weight: 600; cursor: pointer;
}
#play:focus-visible, #timeline:focus-visible, #speed:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
#timeline { flex: 1; accent-color: var(--accent); height: 28px; }
#speed-label { display: flex; align-items: center; gap: 8px; color: var(--ink-soft); }
#speed { font: inherit; padding: 4px 6px; border-radius: 6px; border: 1px solid var(--line); background: var(--card); color: var(--ink); }

@media (max-width: 760px) {
  #main { grid-template-columns: 1fr; grid-template-rows: 1fr 38vh; }
  #panel { border-left: 0; border-top: 1px solid var(--line); }
  #title span { display: none; }
}

"use strict";
// Decodes the inlined run (window.RUN) and builds the indices the renderer and panel use.
// Everything the viewer shows is derived from these logs alone.
const V = (window.V = {});

V.gunzipText = async function (b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream).text();
};

const parseLines = (text) => text.split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));
const fieldIndex = (fields) => Object.fromEntries(fields.map((f, i) => [f, i]));

V.loadRun = async function (raw) {
  const L = raw.layout;
  const rows = parseLines(await V.gunzipText(raw.state));
  const events = raw.events ? parseLines(await V.gunzipText(raw.events)) : [];
  const run = {
    name: raw.name || "",
    layout: L,
    metrics: raw.metrics || [],
    bf: fieldIndex(L.bee_fields || ["id", "x", "y", "life", "carrying", "stunned", "intent"]),
    hf: fieldIndex(L.hornet_fields || ["id", "x", "y", "smell", "hearing", "ambush", "target", "mode"]),
    sf: fieldIndex(L.sound_fields || ["bee", "x", "y", "sound"]),
    lifeCap: L.life_cap || 3 * (L.base_life || 250),
    seasonNames: L.season_names || ["spring", "summer", "autumn", "winter"],
  };
  // Dense tick array: ticks[t] is the state written after tick t resolved.
  const last = rows.length ? rows[rows.length - 1].t : 0;
  run.ticks = new Array(last + 1);
  for (const r of rows) run.ticks[r.t] = r;
  for (let t = 0; t <= last; t++) if (!run.ticks[t]) run.ticks[t] = run.ticks[t - 1] || { t, s: 0, y: 0, b: [], h: [], snd: [] };
  run.lastTick = last;
  run._beeMaps = new Map();
  run._hornetMaps = new Map();

  // Sounds as a flat, time-sorted list.
  run.sounds = [];
  for (const r of rows) {
    for (const s of r.snd || []) {
      run.sounds.push({ t: r.t, bee: s[run.sf.bee], x: s[run.sf.x], y: s[run.sf.y], sound: s[run.sf.sound] });
    }
  }

  // Visual effects and per-bee histories from the events log.
  run.fx = [];
  run.bees = new Map();
  const bee = (id) => {
    if (!run.bees.has(id)) {
      run.bees.set(id, { id, born: null, cause: null, died: null, decisions: [], heard: [], said: [], stings: [], deliveries: [], heals: [] });
    }
    return run.bees.get(id);
  };
  run.seasonEvents = [];
  run.counts = []; // cumulative colony event counts, sampled per event
  for (const e of events) {
    switch (e.kind) {
      case "hatch":
      case "queen_hatch": {
        const b = bee(e.bee);
        b.born = e.t;
        b.cause = e.kind === "queen_hatch" ? "queen" : e.cause;
        run.fx.push({ kind: "hatch", t: e.t, x: e.x, y: e.y, bee: e.bee, queen: e.kind === "queen_hatch" });
        break;
      }
      case "death":
        bee(e.bee).died = e.t;
        run.fx.push({ kind: "death", t: e.t, x: e.x, y: e.y, bee: e.bee });
        break;
      case "sting":
        bee(e.bee).stings.push(e);
        run.fx.push({ kind: "sting", t: e.t, x: e.x, y: e.y, bee: e.bee, hornet: e.hornet, amount: e.amount });
        break;
      case "delivery":
        bee(e.bee).deliveries.push(e);
        run.fx.push({ kind: "delivery", t: e.t, bee: e.bee });
        break;
      case "heal":
        bee(e.bee).heals.push(e);
        break;
      case "decision":
        bee(e.bee).decisions.push(e);
        break;
      case "say":
        bee(e.bee).said.push(e);
        for (const h of e.heard_by || []) bee(h).heard.push({ t: e.t, from: e.bee, text: e.text });
        break;
      case "season":
        run.seasonEvents.push(e);
        break;
    }
  }
  run.fx.sort((a, b) => a.t - b.t);
  run.events = events;
  return run;
};

// Index of the first element of a t-sorted array with t >= value.
V.lowerBound = function (arr, value) {
  let lo = 0, hi = arr.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid].t < value) lo = mid + 1; else hi = mid;
  }
  return lo;
};

// Items of a t-sorted array with from <= t <= to.
V.between = function (arr, from, to) {
  const out = [];
  for (let i = V.lowerBound(arr, from); i < arr.length && arr[i].t <= to; i++) out.push(arr[i]);
  return out;
};

V.tickState = (run, t) => run.ticks[Math.max(0, Math.min(run.lastTick, t))];

V.beeMap = function (run, t) {
  t = Math.max(0, Math.min(run.lastTick, t));
  let m = run._beeMaps.get(t);
  if (!m) {
    m = new Map(run.ticks[t].b.map((b) => [b[run.bf.id], b]));
    if (run._beeMaps.size > 64) run._beeMaps.clear();
    run._beeMaps.set(t, m);
  }
  return m;
};

V.hornetMap = function (run, t) {
  t = Math.max(0, Math.min(run.lastTick, t));
  let m = run._hornetMaps.get(t);
  if (!m) {
    m = new Map(run.ticks[t].h.map((h) => [h[run.hf.id], h]));
    if (run._hornetMaps.size > 64) run._hornetMaps.clear();
    run._hornetMaps.set(t, m);
  }
  return m;
};

// Counts of colony events in [from, to], used by the panel's season summary.
V.countEvents = function (run, from, to) {
  const c = { delivery: 0, sting: 0, hatch: 0, death: 0 };
  for (const f of V.between(run.fx, from, to)) c[f.kind] = (c[f.kind] || 0) + 1;
  return c;
};

"use strict";
// The fixed world: floor, walls, hive and entrances, bloom sites, and the season tint.
// Drawn in world units (one cell = 1) under the view transform, so it stays crisp at any zoom.

V.palette = {
  outside: "#f7f2e8",
  floor: "#fdfaf3",
  wall: "#cdbfa7",
  wallEdge: "#b9aa90",
  hive: "#f5e1a8",
  hiveLine: "rgba(170, 120, 30, 0.22)",
  entrance: "#e3ad3f",
  bloomCell: "#c5e0aa",
  bloomEdge: "#7fb069",
  petal: "#ffffff",
  petalCore: "#e6a92a",
  bee: "#f2c230",
  beeEdge: "#5f440b",
  lifeTrack: "rgba(95, 68, 11, 0.16)",
  life: "#5f440b",
  lifeLow: "#d0452a",
  carry: "#3f8f3a",
  hornet: "#a9501c",
  hornetEdge: "#3f1d07",
  hornetBand: "#2b1406",
  sound1: "#14a39e",
  sound2: "#c42f97",
  sting: "#df2f27",
  sparkle: "#e9a90f",
  select: "#2e2920",
};

// Season colours: the swatch in the header, and a light wash over the map.
V.seasons = {
  spring: { swatch: "#8cc47a", tint: [120, 190, 100, 0.07] },
  summer: { swatch: "#f0c43f", tint: [250, 200, 60, 0.08] },
  autumn: { swatch: "#d9864a", tint: [214, 118, 44, 0.11] },
  winter: { swatch: "#9db3cf", tint: [110, 140, 185, 0.17] },
};

V.prepareMap = function (run) {
  const L = run.layout;
  const walls = [], hive = [], entrances = [];
  L.rows.forEach((row, y) => {
    let start = -1;
    for (let x = 0; x <= row.length; x++) {
      const isWall = row[x] === "#";
      if (isWall && start < 0) start = x;
      if (!isWall && start >= 0) { walls.push([start, y, x - start]); start = -1; }
      if (row[x] === "H") hive.push([x, y]);
      if (row[x] === "E") entrances.push([x, y]);
    }
  });
  const hx = hive.map((c) => c[0]), hy = hive.map((c) => c[1]);
  run.map = {
    walls, hive, entrances,
    hiveBox: hive.length ? [Math.min(...hx), Math.min(...hy), Math.max(...hx) + 1, Math.max(...hy) + 1] : null,
  };
  // The tick at which each tick's season began, for the tint crossfade.
  run.seasonStart = new Int32Array(run.lastTick + 1);
  for (let t = 1; t <= run.lastTick; t++) {
    run.seasonStart[t] = run.ticks[t].s === run.ticks[t - 1].s ? run.seasonStart[t - 1] : t;
  }
};

V.seasonName = (run, t) => run.seasonNames[V.tickState(run, t).s] || "spring";

V.drawMap = function (ctx, run, tau, px) {
  const L = run.layout, P = V.palette, m = run.map;
  ctx.fillStyle = P.floor;
  ctx.fillRect(0, 0, L.width, L.height);

  // Hive interior with a faint comb pattern, clipped to hive cells.
  ctx.fillStyle = P.hive;
  for (const [x, y] of m.hive) ctx.fillRect(x, y, 1, 1);
  if (m.hiveBox) {
    ctx.save();
    ctx.beginPath();
    for (const [x, y] of m.hive) ctx.rect(x, y, 1, 1);
    ctx.clip();
    ctx.strokeStyle = P.hiveLine;
    ctx.lineWidth = px(1);
    const [x0, y0, x1, y1] = m.hiveBox, s = 0.62, h = s * Math.sqrt(3);
    for (let row = 0, y = y0 - 1; y < y1 + 1; row++, y += h / 2) {
      for (let x = x0 - 1 + (row % 2) * 1.5 * s; x < x1 + 1; x += 3 * s) hexPath(ctx, x, y, s);
    }
    ctx.stroke();
    ctx.restore();
  }
  ctx.fillStyle = P.entrance;
  for (const [x, y] of m.entrances) ctx.fillRect(x, y, 1, 1);

  // Walls as merged horizontal runs, with a hairline edge so corridors read clearly.
  ctx.fillStyle = P.wall;
  for (const [x, y, w] of m.walls) ctx.fillRect(x, y, w, 1);
  ctx.strokeStyle = P.wallEdge;
  ctx.lineWidth = px(1);
  ctx.beginPath();
  L.rows.forEach((row, y) => {
    for (let x = 0; x < row.length; x++) {
      if (row[x] !== "#") continue;
      if (y > 0 && L.rows[y - 1][x] !== "#") { ctx.moveTo(x, y); ctx.lineTo(x + 1, y); }
      if (y < L.height - 1 && L.rows[y + 1][x] !== "#") { ctx.moveTo(x, y + 1); ctx.lineTo(x + 1, y + 1); }
      if (x > 0 && row[x - 1] !== "#") { ctx.moveTo(x, y); ctx.lineTo(x, y + 1); }
      if (x < L.width - 1 && row[x + 1] !== "#") { ctx.moveTo(x + 1, y); ctx.lineTo(x + 1, y + 1); }
    }
  });
  ctx.stroke();

  drawBloom(ctx, run, tau, px);

  if (m.hiveBox && px(1) < 0.2) {
    const [x0, y0, x1] = m.hiveBox;
    ctx.fillStyle = "rgba(95, 68, 11, 0.75)";
    ctx.font = `600 ${px(13)}px system-ui, sans-serif`;
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    ctx.fillText("Hive", (x0 + x1) / 2, y0 + px(6));
  }
};

function hexPath(ctx, cx, cy, s) {
  for (let i = 0; i <= 6; i++) {
    const a = (Math.PI / 3) * i;
    const x = cx + s * Math.cos(a), y = cy + s * Math.sin(a);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
}

function drawBloom(ctx, run, tau, px) {
  const P = V.palette, name = V.seasonName(run, Math.floor(tau));
  for (const [season, cells] of Object.entries(run.layout.bloom || {})) {
    if (season === name) {
      for (const [x, y] of cells) {
        ctx.fillStyle = P.bloomCell;
        ctx.fillRect(x + 0.04, y + 0.04, 0.92, 0.92);
        flower(ctx, x + 0.5, y + 0.5, 0.3);
      }
    } else {
      // Sites out of season: a faint dashed outline, so the viewer knows where bloom returns.
      const xs = cells.map((c) => c[0]), ys = cells.map((c) => c[1]);
      ctx.save();
      ctx.strokeStyle = P.bloomEdge;
      ctx.globalAlpha = 0.45;
      ctx.lineWidth = px(1.2);
      ctx.setLineDash([px(4), px(4)]);
      ctx.strokeRect(Math.min(...xs) + 0.1, Math.min(...ys) + 0.1, Math.max(...xs) - Math.min(...xs) + 0.8, Math.max(...ys) - Math.min(...ys) + 0.8);
      ctx.restore();
    }
  }
}

function flower(ctx, cx, cy, r) {
  const P = V.palette;
  ctx.fillStyle = P.petal;
  for (let i = 0; i < 5; i++) {
    const a = (Math.PI * 2 * i) / 5 - Math.PI / 2;
    ctx.beginPath();
    ctx.arc(cx + Math.cos(a) * r * 0.55, cy + Math.sin(a) * r * 0.55, r * 0.42, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = P.petalCore;
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.3, 0, Math.PI * 2);
  ctx.fill();
}

// Season wash, crossfaded over the first ticks of a new season.
V.drawSeasonTint = function (ctx, run, tau) {
  const T = Math.max(0, Math.min(run.lastTick, Math.floor(tau)));
  const cur = V.seasons[V.seasonName(run, T)] || V.seasons.spring;
  const start = run.seasonStart[T];
  const prevName = start > 0 ? V.seasonName(run, start - 1) : null;
  const k = prevName ? Math.min(1, (tau - start) / 8) : 1;
  const prev = (prevName && V.seasons[prevName]) || cur;
  const mix = cur.tint.map((v, i) => prev.tint[i] + (v - prev.tint[i]) * k);
  ctx.fillStyle = `rgba(${mix[0]}, ${mix[1]}, ${mix[2]}, ${mix[3]})`;
  ctx.fillRect(0, 0, run.layout.width, run.layout.height);
};

"use strict";
// Moving things and effects at a fractional time tau. Positions are interpolated between the
// state after tick T and the state after tick T + 1; effects are pure functions of (tau - event tick),
// so any frame can be rendered on its own, in any order, with the same result.

const FX_TICKS = { sound: 6, sting: 5, hatch: 9, death: 14, delivery: 6 };
const TAU = Math.PI * 2;
const ease = (k) => 1 - (1 - k) * (1 - k);

function lerpPos(a, b, f, ix, iy) {
  if (!b) return [a[ix] + 0.5, a[iy] + 0.5];
  return [a[ix] + (b[ix] - a[ix]) * f + 0.5, a[iy] + (b[iy] - a[iy]) * f + 0.5];
}

// Hash for deterministic per-effect variation (no Math.random anywhere in rendering).
function hash(n) {
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  n = Math.imul(n ^ (n >>> 16), 0x45d9f3b);
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}

V.drawLive = function (ctx, run, tau, px, selected) {
  const T = Math.max(0, Math.min(run.lastTick, Math.floor(tau)));
  const f = Math.min(1, Math.max(0, tau - T));
  const P = V.palette, bf = run.bf, hf = run.hf;
  const beesA = run.ticks[T].b, beesB = V.beeMap(run, T + 1);
  const hornetsA = run.ticks[T].h, hornetsB = V.hornetMap(run, T + 1);
  const drawn = [];

  drawSounds(ctx, run, tau, px);

  // Effects under the bees: deaths fade out where the bee fell.
  for (const e of V.between(run.fx, tau - FX_TICKS.death, tau)) {
    if (e.kind !== "death") continue;
    const k = (tau - e.t) / FX_TICKS.death;
    ctx.globalAlpha = 0.7 * (1 - k);
    beeBody(ctx, e.x + 0.5, e.y + 0.5 + 0.15 * k, 0.36 * (1 - 0.3 * k), "#b9ae9c", "#857a68", px, false);
    ctx.globalAlpha = 1;
  }

  // Hornets: dark-edged diamonds, with a faint line to the bee they are chasing.
  const beeNow = V.beeMap(run, T);
  for (const h of hornetsA) {
    const [x, y] = lerpPos(h, hornetsB.get(h[hf.id]), f, hf.x, hf.y);
    const target = h[hf.target];
    if (target != null && target >= 0 && beeNow.has(target)) {
      const b = beeNow.get(target);
      ctx.strokeStyle = "rgba(169, 80, 28, 0.35)";
      ctx.lineWidth = px(1.2);
      ctx.setLineDash([px(3), px(3)]);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(b[bf.x] + 0.5, b[bf.y] + 0.5);
      ctx.stroke();
      ctx.setLineDash([]);
    }
    hornetBody(ctx, x, y, 0.46, px);
    drawn.push({ type: "hornet", id: h[hf.id], x, y, r: 0.46 });
  }

  // Bees: warm yellow, a thin ring for life left out of the cap, a green dot when carrying.
  for (const b of beesA) {
    const id = b[bf.id];
    const [x, y] = lerpPos(b, beesB.get(id), f, bf.x, bf.y);
    const stunned = b[bf.stunned] > 0;
    const r = 0.34;
    if (id === selected) selectionMarks(ctx, run, b, x, y, r, px);
    beeBody(ctx, x, y, r, P.bee, stunned ? P.sting : P.beeEdge, px, true);
    const life = b[bf.life], frac = Math.max(0, Math.min(1, life / run.lifeCap));
    const low = life < 0.25 * (run.layout.base_life || 250);
    ctx.lineWidth = Math.max(px(1.6), 0.07);
    ctx.strokeStyle = P.lifeTrack;
    ctx.beginPath();
    ctx.arc(x, y, r + 0.12, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = low ? P.lifeLow : P.life;
    ctx.beginPath();
    ctx.arc(x, y, r + 0.12, -Math.PI / 2, -Math.PI / 2 + TAU * frac);
    ctx.stroke();
    if (b[bf.carrying]) {
      ctx.fillStyle = P.carry;
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = px(1.2);
      ctx.beginPath();
      ctx.arc(x + 0.3, y - 0.3, 0.15, 0, TAU);
      ctx.fill();
      ctx.stroke();
    }
    drawn.push({ type: "bee", id, x, y, r: r + 0.12 });
  }

  // Effects over the bees: sting flashes, hatch sparkles, delivery pulses.
  for (const e of V.between(run.fx, tau - FX_TICKS.hatch, tau)) {
    const age = tau - e.t;
    if (e.kind === "sting" && age < FX_TICKS.sting) stingFlash(ctx, run, e, age / FX_TICKS.sting, px);
    if (e.kind === "hatch" && age < FX_TICKS.hatch) sparkle(ctx, e, age / FX_TICKS.hatch);
    if (e.kind === "delivery" && age < FX_TICKS.delivery) {
      const b = V.beeMap(run, e.t).get(e.bee);
      if (!b) continue;
      const k = age / FX_TICKS.delivery;
      ctx.strokeStyle = `rgba(233, 169, 15, ${0.9 * (1 - k)})`;
      ctx.lineWidth = px(2.5);
      ctx.beginPath();
      ctx.arc(b[bf.x] + 0.5, b[bf.y] + 0.5, 0.5 + 1.6 * ease(k), 0, TAU);
      ctx.stroke();
    }
  }
  return drawn;
};

function beeBody(ctx, x, y, r, fill, edge, px, stripes) {
  ctx.fillStyle = fill;
  ctx.strokeStyle = edge;
  ctx.lineWidth = Math.max(px(1.2), 0.05);
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
  if (stripes && r / px(1) > 7) {
    ctx.save();
    ctx.clip();
    ctx.fillStyle = "rgba(60, 40, 5, 0.55)";
    ctx.fillRect(x - r * 0.2, y - r, r * 0.22, 2 * r);
    ctx.fillRect(x + r * 0.28, y - r, r * 0.22, 2 * r);
    ctx.restore();
  }
  ctx.stroke();
}

function hornetBody(ctx, x, y, r, px) {
  const P = V.palette;
  ctx.beginPath();
  ctx.moveTo(x, y - r);
  ctx.lineTo(x + r, y);
  ctx.lineTo(x, y + r);
  ctx.lineTo(x - r, y);
  ctx.closePath();
  ctx.fillStyle = P.hornet;
  ctx.fill();
  ctx.save();
  ctx.clip();
  ctx.fillStyle = P.hornetBand;
  ctx.fillRect(x - r, y - r * 0.12, 2 * r, r * 0.24);
  ctx.restore();
  ctx.strokeStyle = P.hornetEdge;
  ctx.lineWidth = Math.max(px(1.3), 0.05);
  ctx.stroke();
}

function selectionMarks(ctx, run, b, x, y, r, px) {
  const P = V.palette, L = run.layout, v = L.vision || 4;
  ctx.strokeStyle = "rgba(46, 41, 32, 0.35)";
  ctx.lineWidth = px(1);
  ctx.setLineDash([px(4), px(3)]);
  ctx.strokeRect(b[run.bf.x] - v, b[run.bf.y] - v, 2 * v + 1, 2 * v + 1);
  const goTo = /^go_to:(-?\d+),(-?\d+)$/.exec(b[run.bf.intent] || "");
  if (goTo) {
    const gx = +goTo[1] + 0.5, gy = +goTo[2] + 0.5;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(gx, gy);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.lineWidth = px(2);
    ctx.strokeStyle = P.select;
    ctx.beginPath();
    ctx.moveTo(gx - 0.3, gy - 0.3); ctx.lineTo(gx + 0.3, gy + 0.3);
    ctx.moveTo(gx + 0.3, gy - 0.3); ctx.lineTo(gx - 0.3, gy + 0.3);
    ctx.stroke();
  }
  ctx.setLineDash([]);
  ctx.strokeStyle = P.select;
  ctx.lineWidth = px(2.2);
  ctx.beginPath();
  ctx.arc(x, y, r + 0.12 + px(5), 0, TAU);
  ctx.stroke();
}

function drawSounds(ctx, run, tau, px) {
  const P = V.palette, radius = run.layout.hearing || 10;
  for (const s of V.between(run.sounds, tau - FX_TICKS.sound, tau)) {
    const k = (tau - s.t) / FX_TICKS.sound;
    const color = s.sound === "sound-2" ? P.sound2 : P.sound1;
    const x = s.x + 0.5, y = s.y + 0.5;
    ctx.globalAlpha = 0.09 * (1 - k);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = color;
    for (const lag of [0, 0.18]) {
      const kk = Math.max(0, Math.min(1, (k - lag) / 0.7));
      if (kk <= 0 || kk >= 1) continue;
      ctx.globalAlpha = 0.85 * (1 - kk);
      ctx.lineWidth = px(2.4);
      ctx.beginPath();
      ctx.arc(x, y, 0.4 + (radius - 0.4) * ease(kk), 0, TAU);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }
}

function stingFlash(ctx, run, e, k, px) {
  const x = e.x + 0.5, y = e.y + 0.5, h = V.hornetMap(run, e.t).get(e.hornet);
  ctx.strokeStyle = V.palette.sting;
  ctx.globalAlpha = 1 - k;
  if (h) {
    ctx.lineWidth = px(2.5);
    ctx.beginPath();
    ctx.moveTo(h[run.hf.x] + 0.5, h[run.hf.y] + 0.5);
    ctx.lineTo(x, y);
    ctx.stroke();
  }
  ctx.fillStyle = "rgba(255, 255, 255, 0.85)";
  ctx.beginPath();
  ctx.arc(x, y, 0.35 + 0.6 * ease(k), 0, TAU);
  ctx.fill();
  ctx.lineWidth = px(2.2);
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (TAU * i) / 8 + 0.2, r0 = 0.45 + 0.5 * ease(k), r1 = r0 + 0.45;
    ctx.moveTo(x + Math.cos(a) * r0, y + Math.sin(a) * r0);
    ctx.lineTo(x + Math.cos(a) * r1, y + Math.sin(a) * r1);
  }
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function sparkle(ctx, e, k) {
  const x = e.x + 0.5, y = e.y + 0.5, n = e.queen ? 8 : 6;
  ctx.globalAlpha = 1 - k;
  for (let i = 0; i < n; i++) {
    const a = TAU * (i / n + hash(e.bee * 31 + i) * 0.15) + k * 1.2;
    const d = 0.35 + 1.1 * ease(k) * (0.7 + 0.5 * hash(e.bee * 17 + i));
    star(ctx, x + Math.cos(a) * d, y + Math.sin(a) * d, 0.2 * (1 - 0.5 * k), i % 2 ? "#ffffff" : V.palette.sparkle);
  }
  ctx.globalAlpha = 1;
}

function star(ctx, x, y, r, color) {
  ctx.fillStyle = color;
  ctx.strokeStyle = "rgba(150, 100, 0, 0.6)";
  ctx.lineWidth = r * 0.15;
  ctx.beginPath();
  for (let i = 0; i < 8; i++) {
    const a = (Math.PI / 4) * i, rr = i % 2 ? r * 0.35 : r;
    ctx.lineTo(x + Math.cos(a) * rr, y + Math.sin(a) * rr);
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
}

"use strict";
// The side panel: the colony at a glance, or the selected bee's life, decisions and memories.

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const DIR_WORDS = { N: "north", NE: "north-east", E: "east", SE: "south-east", S: "south", SW: "south-west", W: "west", NW: "north-west" };
const TRIGGER_WORDS = {
  timer: "regular check", stung: "after a sting", hornet: "saw a hornet", bloom: "saw bloom",
  sound: "heard a sound", arrived: "arrived", home: "entered the hive", life50: "life fell below half",
  life25: "life fell below a quarter", hatched: "just hatched",
};
const MODE_WORDS = { chase: "Chasing", sound: "Following a sound", ambush: "Waiting in ambush", wander: "Wandering" };
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

V.intentWords = function (intent, direction, target) {
  if (!intent) return "No decision yet";
  const [kind, arg] = intent.split(":");
  if (kind === "explore") return `Exploring ${DIR_WORDS[arg || direction] || "onward"}`;
  if (kind === "go_to") {
    const xy = arg ? arg.split(",") : target || [];
    return xy.length === 2 ? `Going to ${xy[0]}, ${xy[1]}` : "Going to a spot";
  }
  return { go_home: "Going home", flee: "Fleeing", wait: "Waiting" }[kind] || cap(kind.replace(/_/g, " "));
};

function soundTag(sound) {
  if (sound === "sound-1") return '<span class="tag s1">sound 1</span>';
  if (sound === "sound-2") return '<span class="tag s2">sound 2</span>';
  return "";
}

const LEGEND = `
<ul class="legend">
  <li><svg width="22" height="22"><circle cx="11" cy="11" r="6" fill="#f2c230" stroke="#5f440b" stroke-width="1.2"/><path d="M11 3 A8 8 0 1 1 3.4 13.5" fill="none" stroke="#5f440b" stroke-width="1.6"/></svg>Bee, ring shows life left</li>
  <li><svg width="22" height="22"><circle cx="9" cy="12" r="6" fill="#f2c230" stroke="#5f440b" stroke-width="1.2"/><circle cx="15.5" cy="6" r="3" fill="#3f8f3a" stroke="#fff" stroke-width="1.2"/></svg>Bee carrying from bloom</li>
  <li><svg width="22" height="22"><path d="M11 2 L20 11 L11 20 L2 11 Z" fill="#a9501c" stroke="#3f1d07" stroke-width="1.3"/><rect x="2" y="10" width="18" height="2.2" fill="#2b1406"/></svg>Hornet</li>
  <li><svg width="22" height="22"><rect x="2" y="2" width="18" height="18" rx="2" fill="#c5e0aa"/><circle cx="11" cy="11" r="4" fill="#fff"/><circle cx="11" cy="11" r="1.8" fill="#e6a92a"/></svg>Bloom</li>
  <li><svg width="22" height="22"><circle cx="11" cy="11" r="8" fill="none" stroke="#14a39e" stroke-width="2.4"/></svg>Sound 1</li>
  <li><svg width="22" height="22"><circle cx="11" cy="11" r="8" fill="none" stroke="#c42f97" stroke-width="2.4"/></svg>Sound 2</li>
  <li><svg width="22" height="22"><g stroke="#df2f27" stroke-width="2.2"><path d="M11 1v5M11 16v5M1 11h5M16 11h5M4 4l3.5 3.5M14.5 14.5L18 18M18 4l-3.5 3.5M7.5 14.5L4 18"/></g></svg>Sting</li>
</ul>`;

V.renderPanel = function (el, run, tau, sel) {
  const T = Math.max(0, Math.min(run.lastTick, Math.floor(tau)));
  const key = `${T}|${sel ? sel.type + sel.id : ""}`;
  if (el.dataset.key === key) return;
  el.dataset.key = key;
  if (sel && sel.type === "bee") el.innerHTML = beeHTML(run, T, sel.id);
  else if (sel && sel.type === "hornet") el.innerHTML = hornetHTML(run, T, sel.id);
  else el.innerHTML = colonyHTML(run, T);
};

function colonyHTML(run, T) {
  const st = run.ticks[T], start = run.seasonStart[T];
  const c = V.countEvents(run, start, T);
  return `
  <h2>The colony</h2>
  <p class="muted">Click or tap a bee to follow its decisions and memories.</p>
  <h3>Right now</h3>
  <div class="stats"><span>Bees alive</span><span>${st.b.length}</span><span>Hornets on the map</span><span>${st.h.length}</span></div>
  <h3>This season so far</h3>
  <div class="stats"><span>Deliveries</span><span>${c.delivery}</span><span>Stings</span><span>${c.sting}</span>
  <span>Hatchings</span><span>${c.hatch}</span><span>Deaths</span><span>${c.death}</span></div>
  <h3>Key</h3>${LEGEND}`;
}

function beeHTML(run, T, id) {
  const h = run.bees.get(id) || { decisions: [], heard: [], stings: [], deliveries: [] };
  const b = V.beeMap(run, T).get(id), bf = run.bf;
  let status, life = 0;
  if (b) {
    life = b[bf.life];
    const cell = run.layout.rows[b[bf.y]][b[bf.x]];
    const parts = [cell === "H" || cell === "E" ? "in the hive" : "out in the maze"];
    if (b[bf.carrying]) parts.push("carrying");
    if (b[bf.stunned] > 0) parts.push("stunned");
    status = `Alive, ${parts.join(", ")}`;
  } else if (h.died != null && h.died <= T) status = `Died at tick ${h.died}`;
  else status = "Not hatched yet";
  const pct = Math.max(0, Math.min(100, (100 * life) / run.lifeCap));
  const low = life < 0.25 * (run.layout.base_life || 250);
  const born = h.born != null ? `Hatched at tick ${h.born}${h.cause === "start" ? ", a founder" : h.cause === "queen" ? ", by the queen" : ""}.` : "";
  const stings = h.stings.filter((e) => e.t <= T).length, deliveries = h.deliveries.filter((e) => e.t <= T).length;
  const decisions = h.decisions.filter((d) => d.t <= T).slice(-6).reverse();
  const memoryOff = run.layout.condition === "no_memory";
  const beliefs = h.decisions.filter((d) => d.t <= T && d.remember).slice(-12).reverse();
  const heard = h.heard.filter((e) => e.t <= T).slice(-4).reverse();
  return `
  <h2>Bee ${esc(id)}</h2>
  <p class="muted">${esc(status)}</p>
  ${b ? `<div class="lifebar${low ? " low" : ""}"><div style="width:${pct.toFixed(1)}%"></div></div>
  <p>Life ${Math.round(life)} of ${run.lifeCap}. ${esc(V.intentWords(b[bf.intent]))}.</p>` : ""}
  <p class="muted">${born} Stung ${stings} ${stings === 1 ? "time" : "times"}, ${deliveries} ${deliveries === 1 ? "delivery" : "deliveries"}.</p>
  <h3>Recent decisions</h3>
  ${decisions.length ? `<ul>${decisions.map((d, i) => decisionHTML(d, i === 0)).join("")}</ul>` : '<p class="muted">None yet.</p>'}
  <h3>What it remembers</h3>
  ${memoryOff ? '<p class="muted">Memory is switched off in this run.</p>'
    : beliefs.length ? `<ul>${beliefs.map((d) => `<li><span class="quote">${esc(d.remember)}</span> <span class="when">tick ${d.t}</span></li>`).join("")}</ul>`
    : '<p class="muted">Nothing written yet.</p>'}
  <h3>Heard at home</h3>
  ${heard.length ? `<ul>${heard.map((e) => `<li><span class="quote">${esc(e.text)}</span> <span class="when">bee ${esc(e.from)}, tick ${e.t}</span></li>`).join("")}</ul>` : '<p class="muted">Nothing yet.</p>'}`;
}

function decisionHTML(d, latest) {
  const intent = V.intentWords(d.intent === "go_to" && d.target ? `go_to:${d.target[0]},${d.target[1]}` : d.intent, d.direction, d.target);
  const extra = [];
  if (d.remember) extra.push(`<div>Remember: <span class="quote">${esc(d.remember)}</span></div>`);
  if (d.say) extra.push(`<div>Says: <span class="quote">${esc(d.say)}</span></div>`);
  return `<li${latest ? ' class="latest"' : ""}><div class="when">tick ${d.t}, ${esc(TRIGGER_WORDS[d.trigger] || d.trigger || "")}</div>
  <div>${esc(intent)} ${soundTag(d.sound)}</div>${extra.join("")}</li>`;
}

function hornetHTML(run, T, id) {
  const h = V.hornetMap(run, T).get(id), hf = run.hf;
  if (!h) return `<h2>Hornet ${esc(id)}</h2><p class="muted">Not on the map now.</p>`;
  const gene = (name) => `<span>${cap(name)}</span><span>${h[hf[name]]} of 10</span>`;
  const target = h[hf.target], mode = h[hf.mode];
  const doing = mode === "chase" && target >= 0 ? `Chasing bee ${target}` : MODE_WORDS[mode] || cap(String(mode || ""));
  return `
  <h2>Hornet ${esc(id)}</h2>
  <p class="muted">${esc(doing)}.</p>
  <h3>Genes</h3>
  <div class="stats">${gene("smell")}${gene("hearing")}${gene("ambush")}</div>
  <p class="muted" style="margin-top:12px">Hornets have no mind. Their genes evolve: the least fit is replaced by a mutated copy of a fitter one.</p>`;
}

"use strict";
// Page wiring: canvas sizing, the view transform, playback, controls, and capture mode.
// Hash parameters: #t=120&bee=3 opens at a tick with a bee selected.
// Capture mode: #capture&from=T0&to=T1&step=S[&bee=ID][&view=x0,y0,x1,y1]; a script then calls
// window.__capture.frame(i) for i in [0, count) and screenshots each frame.

V.state = { tau: 0, playing: false, speed: 6, sel: null, view: { scale: 1, ox: 0, oy: 0 }, userView: false, drawn: [] };

const $ = (id) => document.getElementById(id);
let canvas, ctx, cssW = 0, cssH = 0, dpr = 1, region = null, renderQueued = false;

V.fitView = function () {
  const L = V.run.layout, st = V.state;
  const [x0, y0, x1, y1] = region || [0, 0, L.width, L.height];
  const pad = 14, scale = Math.min((cssW - 2 * pad) / (x1 - x0), (cssH - 2 * pad) / (y1 - y0));
  st.view = { scale, ox: (cssW - scale * (x1 + x0)) / 2, oy: (cssH - scale * (y1 + y0)) / 2 };
  st.fitScale = scale;
  st.userView = false;
};

function resize() {
  const r = $("stage").getBoundingClientRect();
  dpr = window.devicePixelRatio || 1;
  cssW = Math.max(1, Math.round(r.width));
  cssH = Math.max(1, Math.round(r.height));
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  if (!V.state.userView) V.fitView();
  V.render();
}

V.render = function () {
  const run = V.run, st = V.state, v = st.view;
  if (!run) return;
  st.tau = Math.max(0, Math.min(run.lastTick, st.tau));
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = V.palette.outside;
  ctx.fillRect(0, 0, cssW, cssH);
  ctx.setTransform(dpr * v.scale, 0, 0, dpr * v.scale, dpr * v.ox, dpr * v.oy);
  const px = (n) => n / v.scale;
  V.drawMap(ctx, run, st.tau, px);
  V.drawSeasonTint(ctx, run, st.tau);
  const selBee = st.sel && st.sel.type === "bee" ? st.sel.id : null;
  st.drawn = V.drawLive(ctx, run, st.tau, px, selBee);
  if (st.sel && st.sel.type === "hornet") {
    const d = st.drawn.find((o) => o.type === "hornet" && o.id === st.sel.id);
    if (d) {
      ctx.strokeStyle = V.palette.select;
      ctx.lineWidth = px(2.2);
      ctx.beginPath();
      ctx.arc(d.x, d.y, d.r + px(5), 0, Math.PI * 2);
      ctx.stroke();
    }
  }
  updateChrome();
};

V.requestRender = function () {
  if (renderQueued) return;
  renderQueued = true;
  requestAnimationFrame(() => { renderQueued = false; V.render(); });
};

function updateChrome() {
  const run = V.run, st = V.state, T = Math.floor(st.tau), s = V.tickState(run, T);
  const name = run.seasonNames[s.s] || "";
  const text = `${name.charAt(0).toUpperCase()}${name.slice(1)}, year ${s.y + 1}`;
  if ($("season-text").textContent !== text) {
    $("season-text").textContent = text;
    $("season-swatch").style.background = (V.seasons[name] || V.seasons.spring).swatch;
  }
  const slider = $("timeline");
  if (+slider.value !== T) slider.value = T;
  $("play").textContent = st.playing ? "Pause" : "Play";
  $("play").setAttribute("aria-label", st.playing ? "Pause" : "Play");
  V.renderPanel($("panel"), run, st.tau, st.sel);
}

let lastFrame = null;
function loop(now) {
  const st = V.state;
  if (st.playing) {
    if (lastFrame != null) st.tau += (st.speed * Math.min(100, now - lastFrame)) / 1000;
    if (st.tau >= V.run.lastTick) { st.tau = V.run.lastTick; st.playing = false; }
    lastFrame = now;
    V.render();
  } else lastFrame = null;
  requestAnimationFrame(loop);
}

V.setPlaying = function (on) {
  const st = V.state;
  if (on && st.tau >= V.run.lastTick) st.tau = 0;
  st.playing = on;
  V.requestRender();
};

function setupControls() {
  const st = V.state, slider = $("timeline");
  slider.max = V.run.lastTick;
  $("play").addEventListener("click", () => V.setPlaying(!st.playing));
  slider.addEventListener("input", () => { st.tau = +slider.value; V.requestRender(); });
  $("speed").addEventListener("change", (e) => { st.speed = +e.target.value; });
  st.speed = +$("speed").value;
  window.addEventListener("keydown", (e) => {
    if (e.target.tagName === "SELECT" || e.target.tagName === "INPUT") return;
    if (e.key === " ") { e.preventDefault(); V.setPlaying(!st.playing); }
    if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
      st.playing = false;
      st.tau = Math.floor(st.tau) + (e.key === "ArrowRight" ? 1 : -1);
      V.requestRender();
    }
    if (e.key === "Escape") { st.sel = null; V.requestRender(); }
  });
}

function parseHash() {
  const h = location.hash.replace(/^#/, "");
  const capture = h === "capture" || h.startsWith("capture&");
  const p = new URLSearchParams(capture ? h.slice(8) : h);
  const num = (k, d) => (p.has(k) && p.get(k) !== "" && !isNaN(+p.get(k)) ? +p.get(k) : d);
  const view = p.get("view") ? p.get("view").split(",").map(Number) : null;
  return { capture, from: num("from", 0), to: num("to", null), step: num("step", 1), t: num("t", 0),
           bee: num("bee", null), hornet: num("hornet", null), view: view && view.length === 4 ? view : null };
}

V.init = async function () {
  canvas = $("map");
  ctx = canvas.getContext("2d");
  const run = (V.run = await V.loadRun(window.RUN));
  V.prepareMap(run);
  const L = run.layout, p = parseHash(), st = V.state;
  $("title").innerHTML = `Bee colony <span>${esc(L.condition || "")} condition, seed ${esc(L.seed ?? "")}</span>`;
  document.title = `Bee colony, ${L.condition || ""} seed ${L.seed ?? ""}`;
  region = p.view;
  if (p.bee != null) st.sel = { type: "bee", id: p.bee };
  else if (p.hornet != null) st.sel = { type: "hornet", id: p.hornet };
  st.tau = p.capture ? p.from : p.t;
  if (p.capture) {
    document.body.classList.add("capture");
    const to = p.to == null ? run.lastTick : p.to, step = p.step > 0 ? p.step : 1;
    window.__capture = {
      count: Math.floor((to - p.from) / step + 1e-9) + 1,
      frame(i) { st.tau = p.from + i * step; V.render(); return st.tau; },
    };
  } else {
    setupControls();
    V.setupInput(canvas);
    requestAnimationFrame(loop);
  }
  new ResizeObserver(resize).observe($("stage"));
  resize();
